const BY_LOCALE = { fa, en, tr, ar, hi, ps, ckb, pt, ko, fr, zh, de, ru };
const ANCHOR_VALUE = {
  fa: "تعداد سطوح تفصیلی", en: "Number of detail levels", tr: "Detay seviyesi sayısı",
  ar: "عدد المستويات التفصيلية", hi: "विस्तृत स्तरों की संख्या", ps: "د تفصیلي سطحو شمېر",
  ckb: "ژمارەی ئاستەکانی وردەکاری", pt: "Número de níveis de detalhes", ko: "상세 단계 수",
  fr: "Nombre de niveaux de détails", zh: "辅助核算层级数", de: "Anzahl der Detailebenen",
  ru: "Количество аналитических уровней",
};

let src = readFileSync(PATH, "utf8");
let total = 0;
for (const [loc, dict] of Object.entries(BY_LOCALE)) {
  const anchor = `  "settings.swAccDetailLevels": "${ANCHOR_VALUE[loc]}",`;
  if (!src.includes(anchor)) {
    console.error(`ANCHOR NOT FOUND for ${loc}: ${anchor}`);
    process.exit(1);
  }
  const lines = Object.entries(dict).map(([k, v]) => `  "${k}": ${JSON.stringify(v)},`);
  src = src.replace(anchor, anchor + "\n" + lines.join("\n"));
  total += lines.length;
  console.log(`${loc}: +${lines.length}`);
}
writeFileSync(PATH, src);
console.log(`TOTAL inserted: ${total}`);
